DROP TABLE IF EXISTS `conversation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conversation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `user1_id` bigint unsigned NOT NULL COMMENT '鍙備笌鑰咃紙杈冨皬 ID锛',
  `user2_id` bigint unsigned NOT NULL COMMENT '鍙備笌鑰咃紙杈冨ぇ ID锛',
  `last_message_id` bigint unsigned DEFAULT NULL COMMENT '鏈?悗涓?潯娑堟伅',
  `last_message_preview` varchar(100) NOT NULL DEFAULT '' COMMENT '鏈?悗娑堟伅棰勮?锛堟埅鏂?級',
  `last_message_time` datetime(3) DEFAULT NULL COMMENT '鏈?悗娑堟伅鏃堕棿',
  `user1_unread` int unsigned NOT NULL DEFAULT '0' COMMENT 'user1 鐨勬湭璇绘暟锛堟潈濞佸?锛',
  `user2_unread` int unsigned NOT NULL DEFAULT '0' COMMENT 'user2 鐨勬湭璇绘暟锛堟潈濞佸?锛',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users` (`user1_id`,`user2_id`),
  KEY `idx_user1_time` (`user1_id`,`last_message_time` DESC),
  KEY `idx_user2_time` (`user2_id`,`last_message_time` DESC),
  CONSTRAINT `ck_user_order` CHECK ((`user1_id` < `user2_id`))
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='绉佷俊浼氳瘽琛';
/*!40101 SET character_set_client = @saved_cs_client */;

