INSERT INTO `message` VALUES (1,1,2,3,'在吗？想请教你一个问题。',1,'2026-09-14 05:29:48.729',0,'2026-09-14 03:29:48.729','2026-09-14 15:29:48.786'),(2,1,3,2,'在的，你说。',1,'2026-09-14 04:29:48.729',0,'2026-09-14 04:29:48.729','2026-09-14 15:29:48.786'),(3,1,2,3,'MySQL 的分页查询有没有推荐写法？',1,'2026-09-14 05:29:48.729',0,'2026-09-14 05:29:48.729','2026-09-14 15:29:48.786'),(4,1,3,2,'ORDER BY 带上主键，然后限制 size。',1,'2026-09-14 06:29:48.729',0,'2026-09-14 06:29:48.729','2026-09-14 15:29:48.786'),(5,1,2,3,'为什么必须带主键？',1,'2026-09-14 07:29:48.729',0,'2026-09-14 07:29:48.729','2026-09-14 15:29:48.786'),(6,1,3,2,'因为 create_time 可能重复，排序不稳定。',1,'2026-09-14 08:29:48.729',0,'2026-09-14 08:29:48.729','2026-09-14 15:29:48.786'),(7,1,2,3,'明白了，谢谢！',1,'2026-09-14 09:29:48.729',0,'2026-09-14 09:29:48.729','2026-09-14 15:29:48.786'),(8,1,3,2,'不客气。',1,'2026-09-14 10:29:48.729',0,'2026-09-14 10:29:48.729','2026-09-14 15:29:48.786'),(9,1,3,2,'对了，周末有空吗？想约你一起看展。',0,NULL,0,'2026-09-14 12:29:48.729','2026-09-14 15:29:48.786'),(10,1,3,2,'好的，那就这么定了。',0,NULL,0,'2026-09-14 13:29:48.729','2026-09-14 15:29:48.786'),(11,5,7,5,'这是会话 5 的第 1 条测试消息。',1,'2026-09-14 09:29:48.729',0,'2026-09-11 21:29:48.729','2026-09-14 15:29:48.789'),(12,4,6,4,'这是会话 4 的第 1 条测试消息。',1,'2026-09-14 10:29:48.729',0,'2026-09-12 09:29:48.729','2026-09-14 15:29:48.789'),(13,3,5,3,'这是会话 3 的第 1 条测试消息。',1,'2026-09-14 11:29:48.729',0,'2026-09-12 21:29:48.729','2026-09-14 15:29:48.789'),(14,2,4,2,'这是会话 2 的第 1 条测试消息。',1,'2026-09-14 12:29:48.729',0,'2026-09-13 09:29:48.729','2026-09-14 15:29:48.789'),(15,5,5,7,'这是会话 5 的第 2 条测试消息。',1,'2026-09-14 08:29:48.729',0,'2026-09-11 15:29:48.729','2026-09-14 15:29:48.789'),(16,4,4,6,'这是会话 4 的第 2 条测试消息。',1,'2026-09-14 09:29:48.729',0,'2026-09-12 03:29:48.729','2026-09-14 15:29:48.789'),(17,3,3,5,'这是会话 3 的第 2 条测试消息。',1,'2026-09-14 10:29:48.729',0,'2026-09-12 15:29:48.729','2026-09-14 15:29:48.789'),(18,2,2,4,'这是会话 2 的第 2 条测试消息。',1,'2026-09-14 11:29:48.729',0,'2026-09-13 03:29:48.729','2026-09-14 15:29:48.789'),(19,5,7,5,'这是会话 