--
-- Table structure for table `notification`
--

DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `user_id` bigint unsigned NOT NULL COMMENT '鎺ユ敹鑰',
  `type` tinyint NOT NULL COMMENT '绫诲瀷 1鍏虫敞 2鐐硅禐 3璇勮?',
  `actor_id` bigint unsigned NOT NULL COMMENT '瑙﹀彂鑰',
  `post_id` bigint unsigned DEFAULT NULL COMMENT '鐩稿叧鍔ㄦ?',
  `comment_id` bigint unsigned DEFAULT NULL COMMENT '鐩稿叧璇勮?',
  `message_id` bigint unsigned DEFAULT NULL COMMENT '鐩稿叧绉佷俊锛堥?鐣欙級',
  `content` varchar(255) NOT NULL DEFAULT '' COMMENT '鍐呭?蹇?収锛岄槻鍏宠仈鏁版嵁琚?垹鍚庢柇閾',
  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '鏄?惁宸茶?',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_user_read_time` (`user_id`,`is_read`,`create_time` DESC),
  KEY `idx_user_actor_post_type` (`user_id`,`actor_id`,`post_id`,`type`)
) ENGINE=InnoDB AUTO_INCREMENT=503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='閫氱煡琛';
/*!40101 SET character_set_client = @saved_cs_client */;

