--
-- Table structure for table `report`
--

DROP TABLE IF EXISTS `report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `report` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `reporter_id` bigint unsigned NOT NULL COMMENT '涓炬姤浜',
  `target_type` tinyint NOT NULL COMMENT '鐩?爣绫诲瀷 1鐢ㄦ埛 2鍔ㄦ? 3璇勮?',
  `target_id` bigint unsigned NOT NULL COMMENT '鐩?爣 ID锛堝?鎬侊紝鏃犵墿鐞嗗?閿?級',
  `reason_type` tinyint NOT NULL COMMENT '鍘熷洜 1鍨冨溇骞垮憡 2杈遍獋楠氭壈 3鑹叉儏浣庝織 4杩濇硶杩濊? 5鍏朵粬',
  `reason_detail` varchar(255) NOT NULL DEFAULT '' COMMENT '琛ュ厖璇存槑',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '鐘舵? 0寰呭?鐞?1宸插?鐞?2宸查┏鍥',
  `handler_id` bigint unsigned DEFAULT NULL COMMENT '澶勭悊浜猴紙绠＄悊鍛橈級',
  `handle_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '澶勭悊澶囨敞',
  `handle_time` datetime(3) DEFAULT NULL COMMENT '澶勭悊鏃堕棿',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_reporter_target` (`reporter_id`,`target_type`,`target_id`),
  KEY `idx_status_time` (`status`,`create_time` DESC),
  KEY `idx_target` (`target_type`,`target_id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='涓炬姤琛';
/*!40101 SET character_set_client = @saved_cs_client */;

